def task_cost(tok_in, tok_out, p_in, p_out, gpu_share, vec_share,
              fallback_rate, human_cost):
    tok = tok_in * p_in + tok_out * p_out
    fb = fallback_rate * human_cost
    return {"token": tok, "gpu": gpu_share, "vector": vec_share,
            "fallback": fb, "total": tok + gpu_share + vec_share + fb}

def price_floor(cost, margin):
    return cost / (1 - margin)

c = task_cost(3000, 400, 0.008/1000, 0.024/1000, 0.012, 0.004, 0.4, 5.0)
for k, v in c.items():
    print(f"{k:>9}: ¥{v:.3f}")
print(f"兜底占比 = {c['fallback']/c['total']:.1%}")
print(f"报价下限(毛利率70%) = ¥{price_floor(c['total'], 0.70):.2f}")

def margin(q, rev_fn, c_fix=20000.0, c_var=0.5):
    return rev_fn(q) - c_fix - c_var * q

modes = {"席位": (lambda q: 30*1500, None),
         "调用": (lambda q: q*1.5, 1.5),
         "效果": (lambda q: 0.6*q*2.5, 0.6*2.5)}
qs = [10000, 30000, 50000, 60000, 90000]
for name, (f, p) in modes.items():
    print(name, [f"{q//1000}k:{margin(q, f):+,.0f}" for q in qs])
    if p:
        print(f"  盈亏平衡 q* = {20000/(p-0.5):,.0f}")
